typedef int (*OpFunc)(int, int);

int add(int a, int b) { return a + b; }
int sub(int a, int b) { return a - b; }
int mul(int a, int b) { return a * b; }

// Function Pointer Array (Dispatch Table)
OpFunc table[] = { add, sub, mul };

enum { OP_ADD, OP_SUB, OP_MUL, OP_COUNT };

// Dynamic Invocation
int result_add = table[OP_ADD](10, 5);
int result_mul = table[OP_MUL](10, 5);

// Check boundaries
if (OP_SUB < OP_COUNT) { table[OP_SUB](20, 3); }
